"use client";

import { useState, useEffect } from "react";
import { getPublicEventData } from "../actions/public";
import Link from "next/link";

export default function PublicDashboard({ initialEvents }: { initialEvents: any[] }) {
  const [activeEventId, setActiveEventId] = useState(initialEvents[0]?.id || "");
  const [data, setData] = useState<{ 
    latestResults: any[], 
    leaderboard: any[], 
    teams: any[],
    topStars: any[],
    categoryStars: Record<string, any[]>
  }>({ latestResults: [], leaderboard: [], teams: [], topStars: [], categoryStars: {} });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!activeEventId) return;

    const fetchData = async () => {
      setLoading(true);
      const res = await getPublicEventData(activeEventId);
      if (res.success && res.data) {
        setData(res.data);
      }
      setLoading(false);
    };

    fetchData();
    const interval = setInterval(fetchData, 30000);
    return () => clearInterval(interval);
  }, [activeEventId]);

  return (
    <div className="animate-fade-in">
      {/* Event Switcher */}
      <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 'var(--spacing-xl)' }}>
        <div style={{ display: 'flex', background: 'rgba(15, 23, 42, 0.6)', padding: '4px', borderRadius: 'var(--radius-full)', border: '1px solid var(--border-color)' }}>
          {initialEvents.map(event => (
            <button
              key={event.id}
              onClick={() => setActiveEventId(event.id)}
              style={{
                padding: '0.5rem 1.5rem',
                borderRadius: 'var(--radius-full)',
                border: 'none',
                background: activeEventId === event.id ? 'var(--primary)' : 'transparent',
                color: activeEventId === event.id ? 'white' : 'var(--text-secondary)',
                fontWeight: activeEventId === event.id ? 600 : 400,
                cursor: 'pointer',
                transition: 'all 0.2s'
              }}
            >
              {event.name}
            </button>
          ))}
        </div>
      </div>

      {/* Team Ranking First (Full Width) */}
      <section style={{ marginBottom: 'var(--spacing-xxl)' }}>
        <h2 style={{ textAlign: 'center', fontSize: '2rem', marginBottom: 'var(--spacing-lg)', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '15px' }}>
          <span style={{ color: '#FCD34D' }}>🏆</span> Team Standings
        </h2>
        <div className="glass-panel" style={{ padding: 'var(--spacing-lg)' }}>
          {loading ? (
            <div style={{ textAlign: 'center', padding: 'var(--spacing-xl)', color: 'var(--text-muted)' }}>Calculating standings...</div>
          ) : data.leaderboard.length === 0 ? (
            <div style={{ textAlign: 'center', padding: 'var(--spacing-xl)', color: 'var(--text-muted)' }}>No points recorded yet.</div>
          ) : (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 'var(--spacing-md)' }}>
              {data.leaderboard.map((team, index) => (
                <div key={team.id} style={{ 
                  padding: 'var(--spacing-lg)', 
                  background: index === 0 ? 'linear-gradient(135deg, rgba(252, 211, 77, 0.1), rgba(251, 191, 36, 0.05))' : 'rgba(255,255,255,0.02)',
                  border: index === 0 ? '1px solid rgba(252, 211, 77, 0.4)' : '1px solid var(--border-color)',
                  borderRadius: 'var(--radius-lg)',
                  textAlign: 'center',
                  position: 'relative',
                  overflow: 'hidden'
                }}>
                  {index === 0 && <div style={{ position: 'absolute', top: '10px', right: '10px', fontSize: '1.5rem' }}>🥇</div>}
                  {index === 1 && <div style={{ position: 'absolute', top: '10px', right: '10px', fontSize: '1.2rem' }}>🥈</div>}
                  {index === 2 && <div style={{ position: 'absolute', top: '10px', right: '10px', fontSize: '1rem' }}>🥉</div>}
                  
                  <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginBottom: '4px' }}>Rank #{index + 1}</div>
                  <h3 style={{ margin: '0 0 8px 0', color: index === 0 ? '#FCD34D' : 'var(--text-primary)' }}>{team.name}</h3>
                  <div style={{ fontSize: '2.5rem', fontWeight: 'bold', color: 'var(--primary)' }}>{team.points}</div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>TOTAL POINTS</div>
                  <div style={{ height: '4px', background: team.flagColor || 'var(--primary)', position: 'absolute', bottom: 0, left: 0, right: 0 }}></div>
                </div>
              ))}
            </div>
          )}
        </div>
      </section>

      <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 1fr', gap: 'var(--spacing-xl)' }}>
        
        {/* Top Stars & Category Stars */}
        <div>
           <h2 style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: 'var(--spacing-md)' }}>
            <span style={{ color: '#FCD34D', fontSize: '1.5rem' }}>⭐</span> Hall of Fame
          </h2>

          {/* Overall Top 5 */}
          <div className="glass-panel" style={{ padding: 'var(--spacing-md)', marginBottom: 'var(--spacing-lg)' }}>
            <h4 style={{ marginBottom: 'var(--spacing-sm)', color: 'var(--accent)' }}>Overall Top 5 Performers</h4>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--spacing-xs)' }}>
              {data.topStars.map((star, i) => (
                <div key={star.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px', background: 'rgba(255,255,255,0.02)', borderRadius: 'var(--radius-sm)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <div style={{ width: '24px', fontWeight: 'bold', color: i < 3 ? '#FCD34D' : 'var(--text-muted)' }}>{i+1}</div>
                    <div>
                      <div style={{ fontWeight: 600 }}>{star.name}</div>
                      <div style={{ fontSize: '0.7rem', color: star.teamColor || 'var(--primary)' }}>{star.teamName} • {star.categoryName}</div>
                    </div>
                  </div>
                  <div style={{ fontWeight: 'bold', color: 'var(--primary)' }}>{star.points} pts</div>
                </div>
              ))}
            </div>
          </div>

          {/* Category Stars */}
          <h4 style={{ marginBottom: 'var(--spacing-sm)', color: 'var(--text-secondary)' }}>Category Leaders</h4>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--spacing-md)' }}>
            {Object.entries(data.categoryStars).map(([catName, stars]) => (
              <div key={catName} className="glass-panel" style={{ padding: 'var(--spacing-sm)', fontSize: '0.85rem' }}>
                <h5 style={{ margin: '0 0 8px 0', borderBottom: '1px solid var(--border-color)', paddingBottom: '4px' }}>{catName}</h5>
                {stars.map((star, i) => (
                  <div key={star.id} style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px' }}>
                    <span style={{ color: 'var(--text-secondary)' }}>{i+1}. {star.name.split(' ')[0]}</span>
                    <span style={{ fontWeight: 'bold' }}>{star.points}</span>
                  </div>
                ))}
              </div>
            ))}
          </div>
        </div>

        {/* Latest Results & Teams */}
        <div>
          <h2 style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: 'var(--spacing-md)' }}>
            <span style={{ color: 'var(--success)', fontSize: '1.5rem' }}>●</span> Live Results
          </h2>
          <div className="glass-panel" style={{ padding: '0', overflow: 'hidden', marginBottom: 'var(--spacing-xl)' }}>
            {data.latestResults.map((result, index) => (
              <div key={result.id} style={{ 
                padding: 'var(--spacing-md)', 
                borderBottom: index < data.latestResults.length - 1 ? '1px solid var(--border-color)' : 'none',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}>
                <div>
                  <div style={{ fontWeight: 600 }}>{result.candidate.name}</div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>{result.program.name} ({result.candidate.team.name})</div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div style={{ fontWeight: 'bold', color: 'var(--primary)' }}>{result.rank ? `${result.rank} Place` : result.grade ? `Grade ${result.grade}` : 'Result'}</div>
                  <div style={{ fontSize: '0.7rem', color: 'var(--success)' }}>+{result.points} pts</div>
                </div>
              </div>
            ))}
            {data.latestResults.length === 0 && <div style={{ padding: 'var(--spacing-lg)', textAlign: 'center', color: 'var(--text-muted)' }}>Waiting for results...</div>}
          </div>

          <h2 style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: 'var(--spacing-md)' }}>
            <span style={{ color: 'var(--primary)', fontSize: '1.5rem' }}>🚩</span> Teams
          </h2>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: 'var(--spacing-sm)' }}>
            {data.teams.map(team => (
              <div key={team.id} className="glass-panel" style={{ padding: 'var(--spacing-sm)', textAlign: 'center', borderTop: `3px solid ${team.flagColor || 'var(--primary)'}` }}>
                 <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{team.name}</div>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
}
